#!/bin/bash
PS3='Choose an option: '
select opt in 'Start' 'Stop' 'Restart' 'Quit'; do
  case $opt in
    Start) echo 'Starting...'; break ;;
    Quit) echo 'Bye!'; break ;;
  esac
done
